// For each active campaign run, check if any steps are due today.
// A step is due if: start_date + week_offset * 7 days <= today
const runs = $input.all()[0].json;
const today = new Date();
const dueSteps = [];

for (const run of (Array.isArray(runs) ? runs : [])) {
  const startDate = new Date(run.start_date);
  for (const step of (run.steps || [])) {
    const dueDate = new Date(startDate);
    dueDate.setDate(dueDate.getDate() + (step.week_offset || 0) * 7);
    // Due if within the next 24 hours
    if (dueDate >= today && dueDate < new Date(today.getTime() + 86400000)) {
      dueSteps.push({ ...step, run_id: run.id, property_id: run.property_id,
        campaign_run_id: run.id, preset_name: run.preset_name });
    }
  }
}

return dueSteps.map(s => ({ json: s }));
